-- Migration: Import RSUD tariffs (TREAT_TARIF, TARIF_TYPE) and clinic-tariff mappings (CLINIC_TARIF)
-- Total: 32 tariff_types, 10125 tariffs, 9918 clinic_tariffs

CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- 1. Reference table: public.tariff_types (from TARIF_TYPE)
CREATE TABLE IF NOT EXISTS public.tariff_types (
  code TEXT PRIMARY KEY,
  name TEXT NOT NULL
);

ALTER TABLE public.tariff_types ENABLE ROW LEVEL SECURITY;
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'tariff_types' AND policyname = 'tariff_types_select_all'
  ) THEN
    CREATE POLICY tariff_types_select_all ON public.tariff_types FOR SELECT USING (true);
  END IF;
END $$;

ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name;

-- 2. Extend public.tariffs with RSUD columns
ALTER TABLE public.tariffs
  ADD COLUMN IF NOT EXISTS code TEXT,
  ADD COLUMN IF NOT EXISTS kelas TEXT,
  ADD COLUMN IF NOT EXISTS tarif_type TEXT REFERENCES public.tariff_types(code),
  ADD COLUMN IF NOT EXISTS jasa_sarana NUMERIC DEFAULT 0,
  ADD COLUMN IF NOT EXISTS jasa_pelayanan NUMERIC DEFAULT 0,
  ADD COLUMN IF NOT EXISTS is_cito BOOLEAN DEFAULT false;

CREATE INDEX IF NOT EXISTS idx_tariffs_name_trgm ON public.tariffs USING gin (name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_tariffs_code_trgm ON public.tariffs USING gin (code gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_tariffs_kelas ON public.tariffs (kelas);

-- 3. Reference mapping table: public.clinic_tariffs (from CLINIC_TARIF.sql)
CREATE TABLE IF NOT EXISTS public.clinic_tariffs (
  org_unit_code TEXT,
  clinic_id TEXT NOT NULL,
  tariff_code TEXT NOT NULL,
  PRIMARY KEY (clinic_id, tariff_code)
);

CREATE INDEX IF NOT EXISTS idx_clinic_tariffs_tariff_code ON public.clinic_tariffs (tariff_code);

ALTER TABLE public.clinic_tariffs ENABLE ROW LEVEL SECURITY;
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'clinic_tariffs' AND policyname = 'clinic_tariffs_select_all'
  ) THEN
    CREATE POLICY clinic_tariffs_select_all ON public.clinic_tariffs FOR SELECT USING (true);
  END IF;
END $$;

-- 4. Safely remove unreferenced old seed tariffs
DELETE FROM public.tariffs
WHERE tariff_id NOT IN (SELECT DISTINCT tariff_id FROM public.treatment_bills);

